  price_amount_label = '39',
  detail_payload = '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"from-busan-gyeongju-ancient-capital-day-tour","locale":"ko","product_id":"from-busan-gyeongju-ancient-capital-day-tour","seo":{"pageTitle":"부산 출발: 경주 고도(古都) 당일 투어 | AtoC Korea","metaDescription":"부산 출발 경주 당일 소그룹 투어: 아홉산숲 · 불국사(유네스코) · 점심 · 교촌한옥마을+최부자댁+월정교 · 대릉원+황리단길 · 국립경주박물관(겨울엔 동궁과 월지 야경). 부산역·서면역·해운대역 지하철 출구 픽업.","primaryKeywords":["경주 고도(古都) 투어","부산 출발 경주 당일 여행","부산 출발 불국사","신라 왕국 문화유산 투어"],"ogImage":"https://www.atockorea.com/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","description":"부산에서 경주로 떠나는 소그룹 미니밴 당일 투어입니다. 아홉산숲의 대나무길로 하루를 열고, 유네스코 세계유산 불국사를 여유롭게 관람한 뒤, 오후에는 걸어서 도는 두 블록 — 교촌한옥마을·최부자댁에서 월정교까지, 대릉원 왕릉에서 황리단길 카페 거리까지 — 를 지납니다. 마지막은 국립경주박물관(천마총 금관·에밀레종)이며, 겨울(11~2월)에는 같은 시각에 동궁과 월지 야경으로 대체됩니다. 픽업·하차는 부산역 4번 출구, 서면역 4번 출구, 해운대역 5번 출구 — 모두 지하철역입니다."},"catalog_card":{"thumbnail":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","title":"부산 → 경주 고도 일일 투어","priceLabel":"1인 US$39 (정가 $50, 22% 할인)","shortCardDescription":"부산 지하철역 3곳에서 출발하는 경주 당일 소그룹 투어. 오후는 차를 세워두고 걷습니다 — 최부자댁에서 월정교, 대릉원에서 황리단길. 마지막은 국립경주박물관, 겨울에는 동궁과 월지 야경.","tags":["small_group","경주","from_busan","silla_kingdom","ancient_capital"],"rating":0,"reviewCount":0,"slug":"from-busan-gyeongju-ancient-capital-day-tour","subtitle":"소그룹 미니밴 · 영어 가이드 — 아홉산숲, 불국사(유네스코), 교촌한옥마을+최부자댁+월정교, 대릉원+황리단길, 그리고 국립경주박물관(겨울엔 동궁과 월지 야경)까지 하루에.","region":"경주 (부산 출발)","duration":"11.5시간","stopsCount":8,"badges":["소규모 그룹","여유로운 페이스","부산 출발","겨울엔 야경"],"heroImage":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp"},"headlineLine1":"부산 → 경주 고도 일일 투어","headlineLine2":"투어","price":{"amountLabel":"","currency":"USD","per":"person","salePriceUsd":null,"originalPriceUsd":null,"discountPercent":null},"hero":{"imageUrl":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","imagePosition":"center 35%","tagline":"최부자댁에서 월정교로, 대릉원에서 황리단길로 — 오후엔 차를 세워두고 걷습니다","pills":["small_group","경주","ancient_capital"],"meta":{"duration":"약 11.5시간 (첫 픽업 08:10, 마지막 드롭 약 19:50)","region":"경주 (부산 출발)","stops":"8개 정류장","rating":0,"ratingStars":0}},"subnavItems":[{"id":"overview","label":"개요"},{"id":"itinerary","label":"일정"},{"id":"details","label":"상세 정보"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"리뷰"}],"glanceItems":[{"icon":"camera","label":"사진 가치","value":"훌륭함","level":5},{"icon":"mountain","label":"경치 좋음","value":"좋음","level":4},{"icon":"footprints","label":"도보","value":"조금 많음","level":4},{"icon":"cloud-rain","label":"우천 안전","value":"보통","level":3},{"icon":"users","label":"가족 적합","value":"좋음","level":4},{"icon":"gauge","label":"균형","value":"균형 잡힌","level":4}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","location":"아홉산숲","caption":"아홉산숲 — photo 1","alt":"아홉산숲 — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-23-03.webp","location":"아홉산숲","caption":"아홉산숲 — photo 2","alt":"아홉산숲 — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-23-07.webp","location":"아홉산숲","caption":"아홉산숲 — photo 3","alt":"아홉산숲 — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/ahopsan-bamboo/ahopsan-entrance-marker.webp","location":"아홉산숲","caption":"아홉산숲 — photo 7","alt":"아홉산숲 — gallery image 7"},{"id":5,"type":"photo","src":"/images/tours/bulguksa-temple/chatgpt-image-2026-5-11-12-22-06.webp","location":"불국사 (유네스코 세계문화유산)","caption":"불국사 (유네스코 세계문화유산) — photo 1","alt":"불국사 (유네스코 세계문화유산) — gallery image 1"},{"id":6,"type":"photo","src":"/images/tours/bulguksa-temple/chatgpt-image-2026-5-11-12-22-17.webp","location":"불국사 (유네스코 세계문화유산)","caption":"불국사 (유네스코 세계문화유산) — photo 2","alt":"불국사 (유네스코 세계문화유산) — gallery image 2"},{"id":7,"type":"photo","src":"/images/tours/bulguksa-temple/chatgpt-image-2026-5-11-12-22-30.webp","location":"불국사 (유네스코 세계문화유산)","caption":"불국사 (유네스코 세계문화유산) — photo 3