:[{"id":"hero","section_html_id":null,"component":"TourHeroSection","props":{"headlineLine1":"부산 → 경주 고도 일일 투어","headlineLine2":"투어","hero":{"imageUrl":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","imagePosition":"center 35%","tagline":"최부자댁에서 월정교로, 대릉원에서 황리단길로 — 오후엔 차를 세워두고 걷습니다","pills":["small_group","경주","ancient_capital"],"meta":{"duration":"약 11.5시간 (첫 픽업 08:10, 마지막 드롭 약 19:50)","region":"경주 (부산 출발)","stops":"8개 정류장","rating":0,"ratingStars":0}}}},{"id":"subnav","section_html_id":null,"component":"투어탭내비","props":{"subnavItems":[{"id":"overview","label":"개요"},{"id":"itinerary","label":"일정"},{"id":"details","label":"상세 정보"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"리뷰"}]}},{"id":"overview","section_html_id":"overview","component":"투어한눈에보기","props":{"glanceItems":[{"icon":"camera","label":"사진 가치","value":"훌륭함","level":5},{"icon":"mountain","label":"경치 좋음","value":"좋음","level":4},{"icon":"footprints","label":"도보","value":"조금 많음","level":4},{"icon":"cloud-rain","label":"우천 안전","value":"보통","level":3},{"icon":"users","label":"가족 적합","value":"좋음","level":4},{"icon":"gauge","label":"균형","value":"균형 잡힌","level":4}]}},{"id":"atmosphere","section_html_id":null,"component":"투어분위기갤러리","props":{"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","location":"아홉산숲","caption":"아홉산숲 — photo 1","alt":"아홉산숲 — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-23-03.webp","location":"아홉산숲","caption":"아홉산숲 — photo 2","alt":"아홉산숲 — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-23-07.webp","location":"아홉산숲","caption":"아홉산숲 — photo 3","alt":"아홉산숲 — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/ahopsan-bamboo/ahopsan-entrance-marker.webp","location":"아홉산숲","caption":"아홉산숲 — photo 7","alt":"아홉산숲 — gallery image 7"},{"id":5,"type":"photo","src":"/images/tours/bulguksa-