/13b authoring → A-grade pv=6 PASS"},"page_sections":[{"id":"hero","section_html_id":null,"component":"ツアーヒーローセクション","props":{"headlineLine1":"釜山発・慶州古都ツアー","headlineLine2":"ツアー","hero":{"imageUrl":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","imagePosition":"center 35%","tagline":"崔富豪邸から月精橋へ、大陵苑からファンリダンギルへ — 午後は車を停めて歩きます","pills":["small_group","慶州","ancient_capital"],"meta":{"duration":"約11.5時間（最初のお迎え08:10、最終送迎約19:50）","region":"慶州（釜山発）","stops":"8スポット","rating":0,"ratingStars":0}}}},{"id":"subnav","section_html_id":null,"component":"TourTabsNav","props":{"subnavItems":[{"id":"overview","label":"概要"},{"id":"itinerary","label":"旅程"},{"id":"details","label":"詳細"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"クチコミ"}]}},{"id":"overview","section_html_id":"overview","component":"TourAtAGlance","props":{"glanceItems":[{"icon":"camera","label":"写真映え","value":"優秀","level":5},{"icon":"mountain","label":"絶景","value":"良好","level":4},{"icon":"footprints","label":"徒歩","value":"やや多め","level":4},{"icon":"cloud-rain","label":"雨天安全","value":"普通","level":3},{"icon":"users","label":"家族向き","value":"良好","level":4},{"icon":"gauge","label":"バランス","value":"バランスの取れた","level":4}]}},{"id":"atmosphere","section_html_id":null,"component":"TourAtmosphereGallery","props":{"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","location":"アホプサン竹林（아홉산숲）","caption":"アホプサン竹林（아홉산숲） — photo 1","alt":"アホプサン竹林（아홉산숲） — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-23-03.webp","location":"アホプサン竹林（아홉산숲）","caption":"アホプサン竹林（아홉산숲） — photo 2","alt":"アホプサン竹林（아홉산숲） — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-23-07.webp","location":"アホプサン竹林（아홉산숲）","caption":"アホプサン竹林（아홉산숲） — photo 3","alt":"アホプサン竹林（아홉산숲） — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/ahopsan-bamboo/ahopsan-entrance-marker.we