  detail_payload = '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"from-busan-gyeongju-ancient-capital-day-tour","locale":"zh","product_id":"from-busan-gyeongju-ancient-capital-day-tour","seo":{"pageTitle":"从釜山出发：庆州古都一日游 | AtoC Korea","metaDescription":"釜山出发庆州一日小团游：阿弘山竹林 · 佛国寺（UNESCO）· 午餐 · 校村韩屋村+崔富豪宅邸+月精桥 · 大陵苑+皇理团街 · 国立庆州博物馆（冬季为东宫与月池夜景）。釜山站·西面站·海云台站地铁出口接送。","primaryKeywords":["庆州古都游览","从釜山出发庆州一日游","从釜山前往佛国寺","新罗王国文化遗产之旅"],"ogImage":"https://www.atockorea.com/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","description":"从釜山前往庆州的小团迷你巴士一日游。以阿弘山的竹径开启一天，从容游览联合国教科文组织世界遗产佛国寺，下午则走完两个步行街区——从校村韩屋村·崔富豪宅邸到月精桥，从大陵苑王陵到皇理团街咖啡街。最后一站是国立庆州博物馆（天马冢金冠·埃米莱钟），冬季（11月至2月）在同一时刻改为东宫与月池夜景。接送与落客均在釜山站4号出口、西面站4号出口、海云台站5号出口——全部是地铁站。"},"catalog_card":{"thumbnail":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","title":"釜山出发庆州千年古都一日游","priceLabel":"每人 US$39（原价$50，22% 优惠）","shortCardDescription":"从釜山3处地铁站出发的庆州一日小团游。下午把车停下来用脚走——从崔富豪宅邸到月精桥，从大陵苑到皇理团街。最后一站是国立庆州博物馆，冬季则为东宫与月池夜景。","tags":["small_group","庆州","from_busan","silla_kingdom","ancient_capital"],"rating":0,"reviewCount":0,"slug":"from-busan-gyeongju-ancient-capital-day-tour","subtitle":"小团迷你巴士 · 英文导游 —— 阿弘山竹林、佛国寺（UNESCO）、校村韩屋村+崔富豪宅邸+月精桥、大陵苑+皇理团街，以及国立庆州博物馆（冬季为东宫与月池夜景），一日走完。","region":"庆州（从釜山出发）","duration":"11.5小时","stopsCount":8,"badges":["小团体","节奏悠闲","从釜山出发","冬季夜景"],"heroImage":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp"},"headlineLine1":"釜山出发庆州千年古都一日游","headlineLine2":"一日游","price":{"amountLabel":"","currency":"USD","per":"person","salePriceUsd":null,"originalPriceUsd":null,"discountPercent":null},"hero":{"imageUrl":"/images/tours/ahopsan-bamboo/chatgpt-image-2026-5-10-12-22-47.webp","imagePosition":"center 35%","tagline":"从崔富豪宅邸走到月精桥，从大陵苑走到皇理团街——下午把车停下来用脚走","pills":["small_group","庆州","ancient_capital"],"meta":{"duration":"约11.5小时（08:10首次接客，约19:50最后送达）","region":"庆州（从釜山出发）","stops":"8个景点","rating":0,"ratingStars":0}},"subnavItems":[{"id":"overview","labe